code_examples.code:
CREATE TABLE products (
  id INT NOT NULL,
  name TEXT,
  price MONEY,
  PRIMARY KEY (id)
);

INSERT INTO products VALUES (1, 'Pen', 1.20);

-- price unknown yet, so it becomes NULL
INSERT INTO products (id, name) VALUES (2, 'Pencil');

-- fails: id is NOT NULL and not supplied
INSERT INTO products (name, price) VALUES ('Rubber', 1.30);

solution_code.code:
CREATE TABLE products (id INT NOT NULL, name TEXT, price MONEY, PRIMARY KEY (id));
INSERT INTO products VALUES (1, 'Pen', 1.20);
INSERT INTO products (id, name) VALUES (2, 'Pencil');
